    /// Returns the combined perspective view-projection matrix.
    pub fn view_projection(&self, aspect: f32) -> Mat4 {
        let eye = self.eye();
        let view = Mat4::look_at_rh(eye, self.target, Vec3::Y);
        let proj = Mat4::perspective_rh(60_f32.to_radians(), aspect, 0.1, 1000.0);
        proj * view
    }

    /// Returns the planar editor camera transform used by Native 2D mode.
    pub fn to_transform_2d(&self) -> Transform {
        Transform::from_translation(Vec3::new(self.target.x, self.target.y, 100.0))
    }

    /// Returns the same Camera2D projection contract used by runtime rendering.
    pub fn view_projection_2d(&self, viewport: [u32; 2]) -> Mat4 {
        let camera = engine::native_2d::Camera2d {
            orthographic_height: self.distance.max(0.5),
            ..engine::native_2d::Camera2d::default()
        };
        camera
            .view_projection_matrix(&self.to_transform_2d(), viewport)
            .unwrap_or(Mat4::IDENTITY)
    }

    /// Handles cursor-centered pan/zoom for transient Native 2D Scene View mode.
    pub fn handle_input_2d(&mut self, response: &egui::Response) {
        let delta = response.ctx.input(|input| input.pointer.delta());
        if response.dragged_by(egui::PointerButton::Middle)
            || response.dragged_by(egui::PointerButton::Secondary)
        {
            let units_per_pixel = self.distance.max(0.5) / response.rect.height().max(1.0);
            self.target.x -= delta.x * units_per_pixel;
            self.target.y += delta.y * units_per_pixel;
        }
        let scroll = if response.hovered() {
            response.ctx.input(|input| input.smooth_scroll_delta.y)
        } else {
            0.0
        };
        if scroll != 0.0 {
            let before = self.distance.max(0.5);
            let after = (before * (1.0 - scroll * 0.002)).clamp(0.5, 500.0);
            if let Some(pointer) = response.hover_pos() {
                let nx = (pointer.x - response.rect.center().x) / response.rect.height().max(1.0);
                let ny = (response.rect.center().y - pointer.y) / response.rect.height().max(1.0);
                self.target.x += nx * (before - after);
                self.target.y += ny * (before - after);
            }
            self.distance = after;
        }
    }
}

/// Transient presentation mode for the shared persistent Scene View preview world.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum SceneViewMode {
    /// Perspective orbit/fly editing.
    #[default]
    ThreeD,
    /// Orthographic world-XY editing through the runtime Camera2D contract.
    TwoD,
}

